import apiClient from '../config/apiConfig';

/**
 * Monitoring Service - handles exam monitoring operations
 */
class MonitoringService {
  /**
   * Start monitoring for an exam session
   * @param {string} examSessionId - The exam session ID to monitor
   * @returns {Promise} - Response with session details
   */
  async startMonitoring(examSessionId) {
    try {
      const response = await apiClient.post('/monitoring/start', {
        exam_session_id: examSessionId
      });
      return response.data;
    } catch (error) {
      console.error('Error starting monitoring:', error);
      throw error;
    }
  }

  /**
   * Stop monitoring for a session
   * @param {string} sessionId - The monitoring session ID
   * @returns {Promise} - Response confirming stop
   */
  async stopMonitoring(sessionId) {
    try {
      const response = await apiClient.post('/monitoring/stop', {
        session_id: sessionId
      });
      return response.data;
    } catch (error) {
      console.error('Error stopping monitoring:', error);
      throw error;
    }
  }

  /**
   * Get monitoring status
   * @returns {Promise} - List of active monitoring sessions
   */
  async getMonitoringStatus() {
    try {
      const response = await apiClient.get('/monitoring/status');
      return response.data;
    } catch (error) {
      console.error('Error getting monitoring status:', error);
      throw error;
    }
  }

  /**
   * Get alerts for an exam session
   * @param {string} examSessionId - The exam session ID
   * @returns {Promise} - List of alerts
   */
  async getAlerts(examSessionId) {
    try {
      const response = await apiClient.get(`/monitoring/alerts/${examSessionId}`);
      return response.data;
    } catch (error) {
      console.error('Error getting alerts:', error);
      throw error;
    }
  }
}

export default new MonitoringService();
